// Ordering rules only (oxlint covers correctness). Run: npm run lint / npm run lint:fix
import { createTypeScriptImportResolver } from 'eslint-import-resolver-typescript'
import importX from 'eslint-plugin-import-x'
import tseslint from 'typescript-eslint'

// Files generated by `npx shadcn add` — the CLI overwrites them, so we don't restyle them.
// Hand-built components (typography, paper, backdrop, fab, app-bar, list, rating,
// transfer-list, bottom-navigation, speed-dial, stepper) ARE linted.
const cliGenerated = [
  'accordion', 'alert', 'avatar', 'badge', 'breadcrumb', 'button', 'card', 'checkbox',
  'collapsible', 'combobox', 'dialog', 'dropdown-menu', 'input-group', 'input', 'label',
  'pagination', 'popover', 'progress', 'radio-group', 'select', 'separator', 'sheet',
  'skeleton', 'slider', 'sonner', 'switch', 'table', 'tabs', 'textarea', 'toggle-group',
  'toggle', 'tooltip',
].map((n) => `src/components/ui/${n}.tsx`)

export default tseslint.config(
  { ignores: ['dist', 'node_modules', ...cliGenerated] },
  {
    files: ['src/**/*.{ts,tsx}'],
    languageOptions: { parser: tseslint.parser },
    plugins: { '@typescript-eslint': tseslint.plugin, 'import-x': importX },
    settings: { 'import-x/resolver-next': [createTypeScriptImportResolver()] },
    rules: {
      // Props/type members: required first, then optional; each block alphabetical.
      '@typescript-eslint/member-ordering': ['error', {
        interfaces: { memberTypes: 'never', optionalityOrder: 'required-first', order: 'alphabetically-case-insensitive' },
        typeLiterals: { memberTypes: 'never', optionalityOrder: 'required-first', order: 'alphabetically-case-insensitive' },
      }],
      // Imports: libraries → common (@/ alias) → parent → sibling → index; alphabetical within each.
      'import-x/order': ['error', {
        alphabetize: { caseInsensitive: true, order: 'asc' },
        groups: [['builtin', 'external'], 'internal', 'parent', 'sibling', 'index'],
        'newlines-between': 'never',
        pathGroups: [{ group: 'internal', pattern: '@/**' }],
        pathGroupsExcludedImportTypes: ['builtin', 'external'],
      }],
    },
  },
)
